package com.fixmer.genesis.technology.server.remote;
import java.awt.*;import java.nio.file.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import javax.swing.*;
/** Standalone host entry point. No Minecraft/FML/client linkage or credentials. */
public final class ServerLauncher104 {
 private ServerLauncher104(){}
 public static void main(String[] args)throws Exception{
  Path initial=Path.of("").toAbsolutePath();try{Path own=Path.of(ServerLauncher104.class.getProtectionDomain().getCodeSource().getLocation().toURI());if(Files.isRegularFile(own)&&Files.isDirectory(own.getParent().resolve("libraries")))initial=own.getParent();}catch(Exception ignored){}
  if(args.length==0&&!GraphicsEnvironment.isHeadless()){Path folder=initial;SwingUtilities.invokeLater(()->new Window(folder).show());return;}
  String action=args.length==0?"start":args[0];Path folder=args.length>1?Path.of(args[1]).toAbsolutePath():initial;
  if(!Set.of("start","status","restart","stop","acknowledge").contains(action))throw new IllegalArgumentException("start/status/restart/stop <server folder>");
  Path app=deploy(folder);Path output=ServerApp104.root(folder).resolve("logs/launcher.log");Files.createDirectories(output.getParent());Process process=ServerApp104.helper(app,action,folder,java(),output);if(!process.waitFor(60,TimeUnit.SECONDS)){process.destroy();throw new IOException("SERVER104_HELPER_TIMEOUT");}System.out.println(Files.readString(output));if(process.exitValue()!=0)System.exit(2);
 }
 private static Path java(){return Path.of(System.getProperty("java.home"),"bin","java.exe");}
 private static Path deploy(Path server)throws IOException{return ServerApp104.deploy(server,ServerLauncher104.class.getResourceAsStream("/genesis/server59/controller.zip"),ServerLauncher104.class.getResourceAsStream("/genesis/server104/mared.jar"));}
 private static final class Window {
  final JFrame frame=new JFrame("Genesis server");final JTextField folder;final JButton main=new JButton("Запустить сервер");final JLabel status=new JLabel("Выбери папку NeoForge-сервера");final ExecutorService io=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"genesis-host104");t.setDaemon(true);return t;});volatile boolean busy;volatile String lastError="";Path app;javax.swing.Timer timer;
  Window(Path initial){folder=new JTextField(initial.toString());}
  Path server(){return Path.of(folder.getText().trim()).toAbsolutePath();}
  void show(){frame.setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);var body=new JPanel(new BorderLayout(8,12));body.setBorder(BorderFactory.createEmptyBorder(16,16,16,16));var row=new JPanel(new BorderLayout(8,0));row.add(folder);var browse=new JButton("…");row.add(browse,BorderLayout.EAST);browse.addActionListener(e->{var chooser=new JFileChooser(folder.getText());chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);if(chooser.showOpenDialog(frame)==JFileChooser.APPROVE_OPTION)folder.setText(chooser.getSelectedFile().toString());});body.add(row,BorderLayout.NORTH);body.add(main,BorderLayout.CENTER);var bottom=new JPanel(new BorderLayout(8,8));bottom.add(status);var advanced=new JButton("Продвинутые настройки");bottom.add(advanced,BorderLayout.SOUTH);advanced.addActionListener(e->advanced());body.add(bottom,BorderLayout.SOUTH);frame.setContentPane(body);frame.setSize(620,220);frame.setLocationRelativeTo(null);frame.setVisible(true);main.addActionListener(e->{String action="start";try{if(ServerApp104.state(server()).getOrDefault("phase","").equals("RUNNING"))action="restart";}catch(Exception ignored){}run(action);});timer=new javax.swing.Timer(1000,e->refresh());timer.start();frame.addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosed(java.awt.event.WindowEvent e){timer.stop();io.shutdown();}});}
  void refresh(){if(!frame.isDisplayable()||busy)return;try{String phase=ServerApp104.state(server()).getOrDefault("phase","STOPPED");main.setText(phase.equals("RUNNING")?"Перезапустить сервер":"Запустить сервер");status.setText(switch(phase){case "RUNNING"->"Сервер работает";case "STARTING"->"Сервер запускается…";case "STOPPING"->"Сохраняем мир…";case "RESTARTING"->"Перезапускаем…";case "WAITING_FOR_STOP"->"Запуск остановлен. Подробности в логах.";case "RECOVERY_REQUIRED"->"Нужна проверка восстановления. Открой продвинутые настройки.";case "FAILED","BOOTSTRAP_FAILED_RESTORED"->"Ошибка запуска. Подробности в логах.";default->"Готов к запуску";});if(!lastError.isEmpty()&&!phase.equals("RUNNING"))status.setText(lastError);main.setEnabled(!Set.of("STARTING","STOPPING","RESTARTING","WAITING_FOR_STOP","RECOVERY_REQUIRED").contains(phase));}catch(Exception e){status.setText("Не удалось прочитать состояние. Открой логи.");}}
  void run(String action){if(busy)return;busy=true;lastError="";main.setEnabled(false);folder.setEditable(false);Path selected=server();io.execute(()->{try{app=deploy(selected);Path log=ServerApp104.root(selected).resolve("logs/launcher.log");Files.createDirectories(log.getParent());Process p=ServerApp104.helper(app,action,selected,java(),log);if(!p.waitFor(60,TimeUnit.SECONDS)){p.destroy();throw new IOException("timeout");}if(p.exitValue()!=0){String code="SERVER104_OPERATION_FAILED";if(Files.size(log)<32768)for(String line:Files.readString(log).split("\\R"))if(line.matches("[A-Z][A-Z0-9_]{1,100}"))code=line;throw new IOException(code);}}catch(Exception e){ServerApp104.diagnostic(selected,e);lastError=switch(Objects.toString(e.getMessage(),"")){case "SERVER104_ACCEPT_EULA"->"Сначала прими EULA в eula.txt, если согласен с её условиями.";case "SERVER104_PORT_BUSY"->"Порт занят. Останови ранее запущенный сервер.";case "SERVER104_ONE_NEOFORGE_RUNTIME"->"Нужна папка одного установленного NeoForge 1.21.1 сервера.";case "SERVER104_JAVA21"->"Для сервера нужен JDK 21.";default->"Действие не выполнено. Подробности в логах.";};SwingUtilities.invokeLater(()->status.setText(lastError));}finally{busy=false;SwingUtilities.invokeLater(()->{folder.setEditable(true);main.setEnabled(true);refresh();});}});}
  void advanced(){Object[] choices={"Открыть логи","Остановить сервер","Подтвердить проверку восстановления","Закрыть"};int selected=JOptionPane.showOptionDialog(frame,"Сервер работает в выбранной папке. Мир автоматически не откатывается.","Продвинутые настройки",JOptionPane.DEFAULT_OPTION,JOptionPane.PLAIN_MESSAGE,null,choices,choices[0]);try{if(selected==0){Path logs=ServerApp104.root(server()).resolve("logs");Files.createDirectories(logs);Desktop.getDesktop().open(logs.toFile());}else if(selected==1)run("stop");else if(selected==2&&JOptionPane.showConfirmDialog(frame,"Ты проверил логи и совместимость мира с возвращёнными модами?","Восстановление",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)run("acknowledge");}catch(Exception ignored){}}
 }
}
